async fn unstarted_peer_listener_does_not_prove_held_worker_progress() {
    peer_authentication_while_worker_is_held(true, HeldWorkerStartup::GatedUnready).await;
}

#[tokio::test]
async fn delayed_peer_listener_authenticates_after_readiness_before_worker_hold() {
    peer_authentication_while_worker_is_held(true, HeldWorkerStartup::GatedReady).await;
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum HeldWorkerStartup {
    Immediate,
    GatedReady,
    GatedUnready,
}

async fn peer_authentication_while_worker_is_held(
    multithreaded: bool,
    startup: HeldWorkerStartup,
) {
    use futures_util::FutureExt;
    let directory = tempfile::tempdir().unwrap();
    let account = Account::generate();
    let source = node(&directory.path().join("source"), &account);
    let reference = node(&directory.path().join("reference"), &account);
    link(&source, &reference);
    link(&reference, &source);
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    configure(&source, &directory.path().join("source"), address.port());
    configure(&reference, &directory.path().join("reference"), 1);
    let expected = source.identity.public();
    // Diagnostics retain only already-observed phases, never acquire node stores.
    let phases = Arc::new(Mutex::new((std::collections::VecDeque::new(), 0usize)));
    let record_phase = {
        let phases = phases.clone();
        move |label: &str, phase: &str| {
            let phase = format!("{label}: {phase}").chars().take(256).collect::<String>();
            let mut phases = phases.lock().unwrap();
            if phases.0.len() == 32 {
                phases.0.pop_front();
                phases.1 += 1;
            }
            phases.0.push_back(phase);
        }
    };
    let (ready, mut ready_rx) = tokio::sync::oneshot::channel();
    let ready = Mutex::new(Some(ready));
    let source_record = record_phase.clone();
    *source.account_client_test_hook.lock().unwrap() = Some(Arc::new(move |_, phase| {
        source_record("source", &phase);
        if phase.starts_with("responder_admission_acquired_accept_begin")
            && let Some(sender) = ready.lock().unwrap().take()
        {
            let _ = sender.send(());
        }
    }));
    let (startup_release, startup_released) = tokio::sync::oneshot::channel();
    let mut startup_release = Some(startup_release);
    let mut owner = if startup != HeldWorkerStartup::Immediate {
        ActionPeerRuntime::start_multithreaded_with(
            source.clone(), listener, move |node, listener| async move {
                if startup_released.await.is_ok() {
                    node.run_accept_loop(listener).await;
                }
            },
        ).await
    } else if multithreaded {
        ActionPeerRuntime::start_multithreaded(source.clone(), listener).await
    } else {
        ActionPeerRuntime::start(source.clone(), listener).await
    };
    owner.launch();
    let (entered, entered_rx) = tokio::sync::oneshot::channel();
    let (release, released) = std::sync::mpsc::channel::<()>();
    let (noise_started, noise_started_rx) = tokio::sync::oneshot::channel();
    let noise_started = Mutex::new(Some(noise_started));
    *reference.account_client_test_hook.lock().unwrap() = Some(Arc::new(move |_, phase| {
        record_phase("client", &phase);
        if phase == "dial_noise_begin"
            && let Some(sender) = noise_started.lock().unwrap().take()
        {
            let _ = sender.send(());
        }
    }));
    let mut listener_ready = false;
    let mut held = None;
    let mut dial = None;
    let outcome = std::panic::AssertUnwindSafe(async {
        if startup != HeldWorkerStartup::GatedUnready {
            if let Some(release) = startup_release.take() {
                let _ = release.send(());
            }
            // Launch only schedules the handler. Observe its actual accept child
            // before synchronously occupying a worker, including on one thread.
            tokio::time::timeout(std::time::Duration::from_secs(5), &mut ready_rx)
                .await
                .expect("the real listener must reach accept admission before the worker hold")
                .unwrap();
            listener_ready = true;
        }
        held = Some(owner.runtime_handle().spawn(async move {
            let _ = entered.send(());
            let _ = released.recv();
        }));
        tokio::time::timeout(std::time::Duration::from_secs(5), entered_rx)
            .await
            .expect("the actual host worker must enter its controlled hold")
            .unwrap();
        let client = reference.clone();
        let identity = expected.clone();
        dial = Some(tokio::spawn(async move {
            client.privacy_dial(address, &identity).await
        }));
        tokio::time::timeout(std::time::Duration::from_secs(5), noise_started_rx)
            .await
            .expect("the actual client must reach Noise before response observation")
            .unwrap();
        let response =
            tokio::time::timeout(std::time::Duration::from_secs(5), dial.as_mut().unwrap()).await;
        match response {
            Ok(result) => {
                dial = None;
                assert!(multithreaded && listener_ready,
                    "a held single-thread host or unstarted listener cannot answer Noise");
                let response = result
                    .expect("the authenticated client task must join")
                    .expect("the real Noise response must succeed");
                assert_eq!(response.peer_identity(), &expected);
            }
            Err(_) => assert!(
                !multithreaded || !listener_ready,
                "the same host must authenticate while one worker remains held"
            ),
        }
        if startup == HeldWorkerStartup::GatedUnready {
            // The controlled cold-start negative rejects the original oracle;
            // it does not reproduce the historical scheduler timeout's cause.
            assert!(matches!(ready_rx.try_recv(), Err(tokio::sync::oneshot::error::TryRecvError::Empty)));
            assert!(startup_release.is_some());
        }
        assert!(
            !held.as_ref().unwrap().is_finished(),
            "the worker must remain held throughout response observation"
        );
    })
    .catch_unwind()
    .await;
    if outcome.is_err() {
        let phases = phases.lock().unwrap();
        eprintln!("held-worker failure: listener_ready={listener_ready}, held_finished={:?}, omitted_phases={}, phases={:?}",
            held.as_ref().map(|task| task.is_finished()), phases.1, phases.0);
    }
    // Release both controlled prerequisites before any join, including startup
    // assertion failure. Only admitted async work can remain after this point.
    drop(release);
    if let Some(release) = startup_release.take() {
        let _ = release.send(());
    }
    let cleanup = std::panic::AssertUnwindSafe(async {
        let held_result = if let Some(held) = held {
            Some(tokio::time::timeout(std::time::Duration::from_secs(5), held).await)
        } else {
            None
        };
        let mut retirement_failed = false;
        if let Some(mut dial) = dial {
            match tokio::time::timeout(std::time::Duration::from_secs(5), &mut dial).await {
                Ok(result) => { retirement_failed = result.is_err(); }
                Err(_) => {
                    dial.abort();
                    let _ = dial.await;
                    retirement_failed = true;
                }
            }
        }
        *source.account_client_test_hook.lock().unwrap() = None;
        *reference.account_client_test_hook.lock().unwrap() = None;
        owner.stop().await;
        if let Some(result) = held_result {
            result.expect("the released worker must retire").unwrap();
        }
        assert!(!retirement_failed, "the released client must retire");
