    let mut startup_release = Some(startup_release);
    let mut owner = if startup != HeldWorkerStartup::Immediate {
        ActionPeerRuntime::start_multithreaded_with(
            source.clone(), listener, move |node, listener| async move {
                if startup_released.await.is_ok() {
                    node.run_accept_loop(listener).await;
