        ProfileStorageLease::acquire(relay_dir.path()).unwrap(),
        &relay_dir.path().join("relay.log"),
        "pw",
        relay,
    )
    .unwrap();
    let endpoint = IndexedRelayEndpoint::new(office.clone(), None, None);
    let relay_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let relay_address = relay_listener.local_addr().unwrap();
    let reject = Arc::new(AtomicBool::new(true));
    let rejected = Arc::new(AtomicUsize::new(0));
    let (stop, mut stopped) = tokio::sync::oneshot::channel();
    let relay_listener = relay_listener.into_std().unwrap();
    let bob_listener = bob_listener.into_std().unwrap();
    // Both failure endpoints and every actual connection retain one joined
    // reactor owner, independent of Alice and of the synchronous store observer.
    let relay_thread = std::thread::spawn({
        let reject = reject.clone();
        let rejected = rejected.clone();
        move || {
            tokio::runtime::Builder::new_multi_thread().worker_threads(2)
                .enable_all().build().unwrap().block_on(Box::pin(async move {
                    let relay_listener = TcpListener::from_std(relay_listener).unwrap();
                    let bob_listener = TcpListener::from_std(bob_listener).unwrap();
                    let mut connections = tokio::task::JoinSet::new();
                    loop {
                        tokio::select! {
                            _ = &mut stopped => break,
                            incoming = bob_listener.accept() => { drop(incoming.unwrap().0); }
                            incoming = relay_listener.accept() => {
                                let (mut stream, _) = incoming.unwrap();
                                let endpoint = endpoint.clone();
                                let rejected = rejected.clone();
                                let reject_now = reject.load(Ordering::SeqCst);
                                connections.spawn(Box::pin(async move {
                                    if reject_now {
                                        if stream.read_exact(&mut [0u8; 1]).await.is_ok() {
                                            rejected.fetch_add(1, Ordering::SeqCst);
                                        }
                                        return;
                                    }
                                    let identity = DeviceIdentity::from_secret_bytes(relay_keys.0, relay_keys.1);
                                    if let Ok(channel) = super::transport::secure_accept(stream, &identity).await {
                                        let _ = endpoint.serve_connection(channel, None).await;
                                    }
                                }));
                            }
                            result = connections.join_next(), if !connections.is_empty() => {
                                if let Some(Err(error)) = result { assert!(error.is_cancelled(), "relay connection panicked: {error}"); }
                            }
                        }
                    }
                    connections.shutdown().await;
                }));
        }
    });
    let mut host = None;
    let mut flush = None;
    let outcome = std::panic::AssertUnwindSafe(Box::pin(async {
    // No relay is known during channel creation. Bob owns a real accept-close
    // endpoint throughout this test; a released port cannot become a live peer.
    let channel = sender.create_channel("relay retry", vec![bob.public()]).await.unwrap();
    sender.roster.lock().unwrap().update(
        &Announce::new_post_office(&DeviceIdentity::from_secret_bytes(relay_keys.0, relay_keys.1),
            "Relay", relay_address.port()),
        relay_address.ip(), &sender.user_id(),
    );
    let mailbox = RelayMailbox::new(&sender.identity, &bob.public(), &relay_public).unwrap();
    let text = b"one accepted channel survives first relay failure";
    let accepted = sender.enqueue_channel_message_reply_expiring_if(
        channel, text, None, None, |commit| commit(),
    ).unwrap();
    let inner = sender.log.lock().unwrap().get(&accepted).unwrap().unwrap().clone();
    let expected = mailbox.wrap(&inner).unwrap();
        // Install the genuine application reactor but withhold launch until the
        // controlled initial flush ends, so a background exchange cannot consume
        // the fault. Its ordinary recovery owners all run after launch.
        let sender_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        host = Some(IndependentPeerRuntime::start_multithreaded(sender.clone(), sender_listener).await);
        flush = Some(host.as_ref().unwrap().runtime_handle().spawn({
            let sender = sender.clone();
            async move { sender.flush_accepted_channel_message(channel, accepted).await; }
        }));
        tokio::time::timeout(Duration::from_secs(5), flush.as_mut().unwrap()).await
            .expect("initial genuine relay handshake failure must finish within five seconds")
            .unwrap();
        flush = None;
        assert!(rejected.load(Ordering::SeqCst) > 0, "initial flush must send genuine Noise initiator bytes to this relay");
        assert!(sender.log.lock().unwrap().get(&accepted).unwrap().is_some());
        assert_eq!(sender.channel_history(channel, 10).unwrap().iter()
            .filter(|row| row.id == accepted && row.text == text).count(), 1);
        assert!(!office.mailbox_delta_page(&mailbox.id(), None, 16).unwrap().ids.contains(&expected.id));
        reject.store(false, Ordering::SeqCst);
        host.as_mut().unwrap().launch();
        // No resend, flush, replication or manual drain after restoring the SAME
        // endpoint. Observe physical indexed custody rather than sync convergence.
        let outer = tokio::time::timeout(Duration::from_secs(45), Box::pin(async {
            loop {
                let page = office.mailbox_delta_page(&mailbox.id(), None, 16).unwrap();
                let events = office.mailbox_delta_events(&mailbox.id(), &page.cursor, &page.ids, crate::transport::MAX_PLAINTEXT).unwrap();
                if let Some(outer) = events.into_iter().find(|event| event.id == expected.id) {
                    break outer;
                }
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
        })).await.expect("production recovery must retain the exact accepted channel wrapper within the original 45 seconds");
        assert_eq!(outer.ciphertext, expected.ciphertext);
        assert_eq!(mailbox.open(&outer).unwrap().id, accepted);
        assert_ne!(outer.id, accepted);
        assert_ne!(outer.conversation_id, channel);
        assert_eq!(outer.wall_clock, 0);
        assert_eq!(outer.kind, crate::eventlog::EventKind::Message);
        assert!(outer.parents.is_empty());
        assert_ne!(outer.author.ed25519_pub(), &sender.identity.public().ed25519_pub);
        assert!(!outer.ciphertext.windows(text.len()).any(|bytes| bytes == text));
        assert!(!outer.ciphertext.windows(b"relay retry".len()).any(|bytes| bytes == b"relay retry"));
        assert!(office.mailbox_delta_page(&channel, None, 16).unwrap().ids.is_empty());
    })).catch_unwind().await;
    if let Some(flush) = flush {
        flush.abort();
        let _ = flush.await;
    }
    let _ = stop.send(());
    let mut cleanup_failure = None;
    if let Some(host) = host {
        cleanup_failure = std::panic::AssertUnwindSafe(host.stop())
            .catch_unwind()
            .await
            .err();
    }
    let relay_join = tokio::task::spawn_blocking(move || relay_thread.join())
        .await
        .unwrap();
    if let Err(error) = outcome {
        std::panic::resume_unwind(error);
    }
    if let Some(error) = cleanup_failure {
        std::panic::resume_unwind(error);
    }
    relay_join.expect("relay and both failure endpoints must retire");
}

