    pub(in crate::node) async fn flush_accepted_channel_message(
        self: &std::sync::Arc<Self>,
        channel: ConversationId,
        message_id: EventId,
    ) {
        let ready = {
            let mut store = self.delivery.lock().expect("delivery lock");
            match self.recover_delivery(&mut store) {
                Ok(()) => true,
                Err(error) => {
                    log::warn!("accepted channel delivery recovery deferred: {error}");
                    false
                }
            }
        };
        if !ready {
            return;
        }
        let members = self
            .channels
            .lock()
            .expect("channels lock")
            .state(&channel)
            .map(|s| s.members().to_vec());
        if let Some(members) = members {
            self.distribute_channel_message(channel, &members, message_id)
                .await;
        }
    }

    pub(in crate::node) fn enqueue_channel_body_if(
        &self,
        channel: ConversationId,
        wrapped: Vec<u8>,
        request: Option<RequestRecord>,
        authorize: &mut impl FnMut(&mut dyn FnMut() -> Result<(), NodeError>) -> Result<(), NodeError>,
    ) -> Result<EventId, NodeError> {
        self.enqueue_channel_payload_if(channel, wrapped, EventKind::Message, request, authorize)
        );
        material.zeroize();
        Ok(Self {
            id,
            key,
            nonce_key,
            signer,
        })
    }

    pub fn id(&self) -> ConversationId {
        self.id
    }

    fn nonce_for(&self, id: &EventId) -> [u8; 12] {
        let hk = Hkdf::<Sha256>::new(Some(&self.nonce_key), id.as_bytes());
        let mut nonce = [0; 12];
        hk.expand(b"event-nonce", &mut nonce)
            .expect("fixed HKDF output length");
        nonce
    }

    pub fn wrap(&self, inner: &Event) -> Result<Event, MailboxError> {
        if !inner.is_canonical() || !inner.verify_integrity() || !inner.verify_signature() {
            return Err(MailboxError::InvalidEnvelope);
        }
        let mut serialized =
            bincode::serialize(inner).map_err(|_| MailboxError::InvalidEnvelope)?;
        if serialized.len() > MAX_INNER_BYTES {
            serialized.zeroize();
            return Err(MailboxError::TooLarge);
        }
        let bucket = BUCKETS
            .iter()
            .copied()
            .find(|size| serialized.len() + 4 <= *size)
            .ok_or(MailboxError::TooLarge)?;
        let mut plaintext = vec![0u8; bucket];
        plaintext[..4].copy_from_slice(&(serialized.len() as u32).to_le_bytes());
        plaintext[4..4 + serialized.len()].copy_from_slice(&serialized);
        serialized.zeroize();
        let nonce = self.nonce_for(&inner.id);
        let cipher = Aes256Gcm::new_from_slice(&self.key).expect("valid key length");
        let aead_nonce = Nonce::try_from(nonce.as_slice()).expect("valid nonce length");
        let encrypted = cipher.encrypt(
            &aead_nonce,
            Payload {
                msg: &plaintext,
                aad: self.id.as_bytes(),
            },
        );
        plaintext.zeroize();
        let ciphertext = encrypted.map_err(|_| MailboxError::InvalidEnvelope)?;
        let mut body = Vec::with_capacity(12 + ciphertext.len());
        body.extend_from_slice(&nonce);
        body.extend_from_slice(&ciphertext);
        let seq = u64::from_le_bytes(nonce[..8].try_into().unwrap());
        Ok(Event::new(
            &self.signer,
            self.id,
            seq,
            vec![],
            0,
            0,
            EventKind::Message,
            body,
                ids,
                complete,
                reset,
            })
        })
    }

    pub(crate) fn mailbox_delta_events_at(
        &self,
        conv: &ConversationId,
        cursor: &MailboxCursor,
        ids: &[EventId],
        max_bytes: usize,
        now: u64,
    ) -> Result<Vec<Event>, LogError> {
        if ids.len() > 1500 || max_bytes == 0 || max_bytes > crate::transport::MAX_PLAINTEXT {
            return Err(LogError::InvalidPageBudget);
        }
        self.session_transaction(now, None, |c, cutoff| {
            let current = self.mailbox_cursor_on(c, conv, cutoff)?;
            if !cursor.accepts(&current) { return Err(LogError::StaleCursor); }
            let mut encoded = 0usize;
            let mut allocated = 0usize;
            // Check every selected scalar before reading the first body. No
            // supplied ID can escape its mailbox or the delivered prefix.
            for id in ids {
                let sizes: Option<(i64,i64)> = c.prepare_cached("SELECT encoded_bytes,stored_bytes FROM retained_events WHERE domain=?1 AND id=?2 AND conversation=?3 AND commit_ordinal<?4")?.query_row(params![RELAY_EVENTS.0.as_slice(), id.as_bytes().as_slice(),conv.as_bytes().as_slice(),cursor.after], |r| Ok((r.get(0)?,r.get(1)?))).optional()?;
                let (wire, stored) = sizes.ok_or(LogError::StaleCursor)?;
                let wire = usize::try_from(wire).map_err(|_| invalid("negative mailbox wire size"))?;
                let stored = usize::try_from(stored).map_err(|_| invalid("negative mailbox stored size"))?;
                encoded = encoded.checked_add(wire).ok_or(LogError::RepositoryCounterExhausted)?;
                allocated = stored.checked_mul(3).and_then(|n| n.checked_add(std::mem::size_of::<Event>())).and_then(|n| n.checked_add(allocated)).ok_or(LogError::RepositoryCounterExhausted)?;
            }
            if encoded > max_bytes { return Err(LogError::PageBudgetTooSmall { required: encoded }); }
            if allocated > 4 * 1024 * 1024 { return Err(LogError::PageBudgetTooSmall { required: allocated }); }
            ids.iter().map(|id| self.repository.get_on(c,id)?.ok_or(LogError::StaleCursor)).collect()
        })
    }
}

