    pub fn history(
        &self,
        conversation: ConversationId,
        limit: usize,
    ) -> Result<Vec<HistoryEntry>, super::NodeError> {
        self.project_history(conversation, None, HistorySelection::Recent(limit))
            .map(|context| context.map_or_else(Vec::new, |context| context.messages))
    }

    /// Canonical metadata ranks persist across ordinary reads. SQL selects the
    /// requested ranks and admits their byte cost before any transcript body load.
    pub(in crate::node) fn project_history(
        &self,
        conversation: ConversationId,
        account: Option<&str>,
        selection: HistorySelection<'_>,
    ) -> Result<Option<super::search::SearchContext>, super::NodeError> {
        use super::delivery_store::DeliveryTransaction;
        use super::transcript_repository::{FILES, RECEIVED, SENT, TranscriptPageLimit};
        use crate::eventlog::repository::order::{
            CausalOrder, OrderReadiness, OrderWorkBudget,
            combined::{HistoryAppendPrefix, HistoryInputStamp, HistorySelector},
        };
        use std::collections::{HashMap, HashSet};
        let selected_ids: Vec<EventId>;
        let selection = match selection {
            HistorySelection::Selected(ids) => {
                if ids
                    .len()
                    .checked_mul(std::mem::size_of::<EventId>())
                    .is_none_or(|bytes| bytes > 8 * 1024 * 1024)
                {
            self.recover_delivery(&mut store).map_err(NodeError::Log)?;
            let wrapped = wrapped
                .take()
                .ok_or_else(|| NodeError::InvalidInput("accept is single-use".into()))?;
            let book = self.channels.lock().expect("channels lock");
            let state = book
                .state(&channel)
                .ok_or_else(|| NodeError::Channel("unknown channel".into()))?;
            if !self.channel_identity_is_current(state)?
                || state.pending_invite()
                || state.is_dissolved()
            {
                return Err(NodeError::Channel("not an active channel member".into()));
            }
            let log = self.log.lock().expect("log lock");
            let (mut transaction, id) =
                self.prepare_channel_outgoing_locked(channel, wrapped, kind, &log, state)?;
            drop(log);
            if let Some(mut record) = request.take() {
                record.message_id = id;
                record.accepted_at_ms = now_millis();
                transaction = DeliveryTransaction::Requested {
                    request: record,
                    transaction: Box::new(transaction),
                };
            }
            self.begin_delivery_intent(&mut store, transaction)
                .map_err(NodeError::Log)?;
            drop(book);
            result = Some(id);
            Ok(())
        })?;
        let id = result.ok_or_else(|| {
            NodeError::Authorization("authorization did not execute acceptance".into())
        })?;
        let mut store = self.delivery.lock().expect("delivery lock");
        if let Err(error) = self.recover_delivery(&mut store) {
            log::warn!("accepted channel message awaits local recovery: {error}");
        }
        drop(store);
        // Acceptance already committed: preparation failure cannot turn its
        // exact returned ID into a retryable send failure. The worker resumes it.
        if let Err(error) = self.prepare_channel_admission(channel, &mut preparation) {
            log::debug!("accepted channel metadata awaits preparation: {error}");
        }
        self.process_channel(channel);
        Ok(id)
    }
}

