    /// One recipient's full-publication repair. Completion parks publication
    /// scheduling only; custody still requires this exact authenticated probe.
    pub(in crate::node) async fn repair_channel_relay_publication(
        &self,
        channel: &mut crate::transport::SecureChannel<tokio::net::TcpStream>,
        recipient: &PublicIdentity,
        conversation: ConversationId,
        event: EventId,
    ) -> Result<bool, super::session::SessionError> {
        let result = self
            .opaque_relay_round_with_intent_observing(
                channel,
                recipient,
                Some(conversation),
                Some(event),
                MailboxIntent::HistoryPublication,
                true,
            )
            .await?;
        if !result.quiet || !self.publication_proofs_current(&result.proofs)? {
            return Ok(false);
        }
        let mut mailboxes = vec![
            RelayMailbox::new(&self.identity, recipient, channel.peer_identity())
                .map_err(|error| super::session::SessionError::Serialization(error.to_string()))?,
        ];
        if self.bridge_directory_allowed() {
            mailboxes.push(
                RelayMailbox::federated(&self.identity, recipient).map_err(|error| {
                    super::session::SessionError::Serialization(error.to_string())
                })?,
            );

